from torch import nn
class MaskedAttention(nn.Module):
 def __init__(self, embed_dim=32, num_heads=4, dropout=0.1, batch_first=True):
  super().__init__()
  self.attention=nn.MultiheadAttention(embed_dim,num_heads,dropout=dropout,batch_first=batch_first)
 def forward(self, query, key, value, key_padding_mask):
  return self.attention(query=query,key=key,value=value,key_padding_mask=key_padding_mask,need_weights=False)

